import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { create } from 'zustand';

export interface Card {
  id: string;
  deckId: string;
  front: string;
  back: string;
  createdAt: string;
}

export interface Deck {
  id: string;
  title: string;
  description: string;
  cards: Card[];
}

interface FlashcardHubState {
  decks: Deck[];
  activeDeck: Deck | null;
  quizMode: boolean;
  currentCardIndex: number;
  score: number;
  setDecks: (decks: Deck[]) => void;
  setActiveDeck: (deck: Deck | null) => void;
  startQuiz: (deck: Deck) => void;
  answerQuiz: (correct: boolean) => void;
  exitQuiz: () => void;
  upsertCard: (card: Card) => void;
}

export const useFlashcardHub = create<FlashcardHubState>((set) => ({
  decks: [],
  activeDeck: null,
  quizMode: false,
  currentCardIndex: 0,
  score: 0,
  setDecks: (decks) => set({ decks }),
  setActiveDeck: (deck) => set({ activeDeck: deck }),
  startQuiz: (deck) => set({ activeDeck: deck, quizMode: true, currentCardIndex: 0, score: 0 }),
  answerQuiz: (correct) => set((state) => ({
    currentCardIndex: state.currentCardIndex + 1,
    score: correct ? state.score + 1 : state.score
  })),
  exitQuiz: () => set({ quizMode: false, currentCardIndex: 0, score: 0 }),
  upsertCard: (card) => set((state) => {
    if (!state.activeDeck) return state;
    const updatedCards = state.activeDeck.cards.some(c => c.id === card.id)
      ? state.activeDeck.cards.map(c => c.id === card.id ? card : c)
      : [...state.activeDeck.cards, card];
    const updatedDeck = { ...state.activeDeck, cards: updatedCards };
    return {
      activeDeck: updatedDeck,
      decks: state.decks.map(d => d.id === updatedDeck.id ? updatedDeck : d)
    };
  })
}));
